import 'package:flutter/material.dart';import '../../core/hotels/hotel_repository.dart';import '../../core/state/app_controller.dart';import '../../models/hotel_models.dart';import 'hotel_owner_manage_screen.dart';
class HotelOwnerDashboard extends StatefulWidget{const HotelOwnerDashboard({super.key});@override State<HotelOwnerDashboard>createState()=>_S();}class _S extends State<HotelOwnerDashboard>{List<HotelSummary>items=[];bool busy=true;@override void didChangeDependencies(){super.didChangeDependencies();if(items.isEmpty)_load();}Future<void>_load()async{try{items=await HotelRepository(AppControllerScope.of(context).apiClient).myHotels();}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>SafeArea(child:RefreshIndicator(onRefresh:_load,child:ListView(padding:const EdgeInsets.all(14),children:[const Text('My Hotels',style:TextStyle(fontSize:20,fontWeight:FontWeight.w900)),const Text('Only admin-approved hotels appear to customers.',style:TextStyle(fontSize:10,color:Colors.black54)),const SizedBox(height:14),if(busy)const Center(child:CircularProgressIndicator())else if(items.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(22),child:Text('No hotel added yet. Use Add hotel to submit one for approval.')))else for(final h in items)Card(child:ListTile(onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>HotelOwnerManageScreen(hotel:h))),leading:const CircleAvatar(child:Icon(Icons.hotel_rounded)),title:Text(h.name,style:const TextStyle(fontSize:13,fontWeight:FontWeight.w800)),subtitle:Text('${h.city}\n${h.approvalStatus??'Pending'}',style:const TextStyle(fontSize:10)),isThreeLine:true,trailing:Icon(h.approvalStatus=='Approved'?Icons.verified_rounded:h.approvalStatus=='Rejected'?Icons.cancel_rounded:Icons.hourglass_top_rounded,color:h.approvalStatus=='Approved'?Colors.green:h.approvalStatus=='Rejected'?Colors.red:Colors.orange))]))));}
